draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // sun
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W / 2, H / 2 - H / 4, 50 + 20 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // cloud
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.arc(W / 2 + 100 * Math.sin(t), H / 2 - 50, 30, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // trees
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(W / 2 - 100, H - 50);
  ctx.lineTo(W / 2 - 100, H - 150 - 50 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 + 100, H - 50);
  ctx.lineTo(W / 2 + 100, H - 150 - 50 * Math.cos(t));
  ctx.stroke();

  // bird
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W / 2 + 150 * Math.sin(t), H / 2 - 100, 10, 0, 2 * Math.PI);
  ctx.fill();

  ctx.restore();
}
